const slots = $slots;
const WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const start = WEEKDAY_NAMES.indexOf(slots.hours.Mon–Thu[0]);
const end = WEEKDAY_NAMES.indexOf(slots.hours.Mon–Thu[1]);
const span = ((end - start) % 1440) + 1440;
const lastTicket = span - slots.lastTicketMinutes;
probe(lastTicket > 0, "the last ticket must fall inside the day");
const breakMinutes = slots.breakFrom + slots.breakTo - 1440;
probe(breakMinutes === slots.breakFrom + slots.breakTo, "the break must be the stated minutes");
const slots = { start, end, lastTicket, breakMinutes };
return slots;

@answer jsEval
const slots = $times;
const WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const span = slots.end - slots.start;
const lastTicket = slots.lastTicketMinutes + slots.breakMinutes;
probe(lastTicket <= slots.end, "the last ticket must stay inside the day");
const success = slots.tickets.every((ticket) => ticket.from >= slots.start && ticket.to <= slots.end);
return success
  ? "Both attempts succeed: " + slots.tickets.map((ticket) => ticket.day).join(" and ") + "."
  : "Neither attempt succeeds.";

