@times jsEval
const slots = $slots;
const minutesOf = (hhmm) => { const parts = String(hhmm).split(":"); return Number(parts[0]) * 60 + Number(parts[1]); };
const lastTicketMinutes = minutesOf(slots.lastTicketHours) + slots.lastTicketMinutes;
const breakMinutes = minutesOf(slots.breakFrom) + slots.breakToMinutes;
const openUntil = slots.hours[slots.person].to;
const windowEnd = minutesOf(openUntil);
const ticketAttempts = slots.tickets.map((ticket) => ({ day: ticket.day, from: minutesOf(ticket.from), to: minutesOf(ticket.to) }));
const failed = ticketAttempts.filter((attempt) => attempt.to > windowEnd);
probe(failed.length === 1, "exactly one of the two tickets must fit the window");
const success = ticketAttempts.find((attempt) => attempt !== failed[0]);
probe(success !== undefined, "the two tickets must leave a window");
probe(success.from > failed[0].from, "the successful ticket must arrive after the failed one");
return { failed: failed[0], success: success };

